Method.Implementation:
Set startTS=..NormTS(pStart) Set endTS=..NormTS(pEnd)
Write !!,"MessageCounter Rollups",! Write "RangeStart=",startTS,! Write "RangeEnd =",endTS,!!
Kill monthCounts,weekCounts,excluded,indexOnly,hybrid,sqlUsed,globalUsed Set grandTotal=0
Kill nsList Do ##class(%SYS.Namespace).ListAll(.nsList)
Set ns="" For { Set ns=$Order(nsList(ns)) Quit:ns="" Continue:$Extract(ns,1,1)="%"
; switch namespace Set okNs=1 New $NAMESPACE Try { Set $NAMESPACE=ns } Catch ex { Set okNs=0 } If 'okNs { Set excluded(ns)="CANNOT ENTER NAMESPACE" Continue }
; index coverage if present Set idxMin="", idxMax="" If $Data(^Ens.MessageHeaderI("TimeCreated")) { Set idxMin=$Order(^Ens.MessageHeaderI("TimeCreated","")) Set idxMax=$Order(^Ens.MessageHeaderI("TimeCreated",""),-1) }
; no data at all? If (idxMin="")&( $Order(^Ens.MessageHeaderD(""))="" ) { Set excluded(ns)="NO MESSAGE DATA" Continue }
Set usedI=0, usedS=0, usedG=0, usedH=0
If idxMin'="" { ; overlap range Set ovStart=..MaxTS(startTS,idxMin) Set ovEnd=..MinTS(endTS,idxMax)
If ..TSLeq(ovStart,ovEnd) { Do ..RollupFromIndexRange(ovStart,ovEnd,1,1,.monthCounts,.weekCounts,.grandTotal) Set usedI=1 }
; left gap [start .. idxMin) if start < idxMin If (idxMin ]] startTS) { Do ..RollupFallbackRange(startTS,idxMin,1,0,.monthCounts,.weekCounts,.grandTotal,.usedS,.usedG) Set usedH=1 }
; right gap (idxMax .. end] if end > idxMax If (endTS ]] idxMax) { Do ..RollupFallbackRange(idxMax,endTS,0,1,.monthCounts,.weekCounts,.grandTotal,.usedS,.usedG) Set usedH=1 }
If usedI & usedH Set hybrid(ns)="" If usedI & ('usedH) Set indexOnly(ns)="" If usedS Set sqlUsed(ns)="" If usedG Set globalUsed(ns)="" Continue }
; no index => full fallback Do ..RollupFallbackRange(startTS,endTS,1,1,.monthCounts,.weekCounts,.grandTotal,.usedS,.usedG) If usedS Set sqlUsed(ns)="" If usedG Set globalUsed(ns)="" If ('usedS)&('usedG) Set excluded(ns)="NO INDEX; SQL failed; GLOBAL failed" }
; ---- print months ---- Write "MONTHLY TOTALS",! Write "Month",?15,"Count",! Set mon="" Set monthTotal=0 For { Set mon=$Order(monthCounts(mon)) Quit:mon="" Write mon,?15,+$Get(monthCounts(mon)),! Set monthTotal=monthTotal+$Get(monthCounts(mon)) } Write "MONTH TOTAL",?15,monthTotal,!!
; ---- print weeks ---- Write "WEEKLY TOTALS (Monday start)",! Write "Week Of",?15,"Week End",?30,"Count",! Set wk="" Set weekTotal=0 For { Set wk=$Order(weekCounts(wk)) Quit:wk=""
Set wkH=$ZDATETIMEH(wk_" 00:00:00",3) Set wkDay=$Piece(wkH,",",1) Set wkEndStr=$ZDATE(wkDay+6,3)
Write wk,?15,wkEndStr,?30,+$Get(weekCounts(wk)),! Set weekTotal=weekTotal+$Get(weekCounts(wk)) } Write "WEEK TOTAL",?30,weekTotal,!!
Write "GRAND TOTAL",?15,grandTotal,! Write "CHECK (months sum)",?15,monthTotal,! Write "CHECK (weeks sum)",?15,weekTotal,!!
If $Data(hybrid) { Write "NAMESPACES COUNTED VIA HYBRID (INDEX + GAP FILL)",! Set n="" For { Set n=$Order(hybrid(n)) Quit:n="" Write n,! } Write ! } If $Data(indexOnly) { Write "NAMESPACES COUNTED VIA INDEX ONLY",! Set n="" For { Set n=$Order(indexOnly(n)) Quit:n="" Write n,! } Write ! } If $Data(sqlUsed) { Write "NAMESPACES USING SQL (some/all segments)",! Set n="" For { Set n=$Order(sqlUsed(n)) Quit:n="" Write n,! } Write ! } If $Data(globalUsed) { Write "NAMESPACES USING GLOBAL (some/all segments)",! Set n="" For { Set n=$Order(globalUsed(n)) Quit:n="" Write n,! } Write ! } If $Data(excluded) { Write "EXCLUDED NAMESPACES",! Set e="" For { Set e=$Order(excluded(e)) Quit:e="" Write e,": ",excluded(e),! } Write ! }
Quit

Set pStatus=""
Set total=0

; switch namespace
Set ok=1
New $NAMESPACE
Try { Set $NAMESPACE=pNamespace } Catch ex { Set ok=0 }
If 'ok { Set pStatus="CANNOT ENTER NAMESPACE" Quit 0 }

; index coverage if present
Set idxMin="", idxMax=""
If $Data(^Ens.MessageHeaderI("TimeCreated")) {
    Set idxMin=$Order(^Ens.MessageHeaderI("TimeCreated",""))
    Set idxMax=$Order(^Ens.MessageHeaderI("TimeCreated",""),-1)
}

; no data at all?
If (idxMin="")&( $Order(^Ens.MessageHeaderD(""))="" ) {
    Set pStatus="NO MESSAGE DATA"
    Quit 0
}

Set usedI=0, usedS=0, usedG=0, usedH=0

If idxMin'="" {
    Set ovStart=..MaxTS(pStartTS,idxMin)
    Set ovEnd=..MinTS(pEndTS,idxMax)

    If ..TSLeq(ovStart,ovEnd) {
        Set total=total + ..CountUsingIndexRange(ovStart,ovEnd,1,1)
        Set usedI=1
    }

    If (idxMin ]] pStartTS) {
        Set total=total + ..CountFallbackRange(pStartTS,idxMin,1,0,.usedS,.usedG)
        Set usedH=1
    }

    If (pEndTS ]] idxMax) {
        Set total=total + ..CountFallbackRange(idxMax,pEndTS,0,1,.usedS,.usedG)
        Set usedH=1
    }

    If usedI & usedH Set pStatus="OK (HYBRID)"
    If usedI & ('usedH) Set pStatus="OK (INDEX)"
    If usedS Set pStatus=pStatus_" + SQL"
    If usedG Set pStatus=pStatus_" + GLOBAL"
    Quit total
}

; no index => fallback full range
Set total=..CountFallbackRange(pStartTS,pEndTS,1,1,.usedS,.usedG)
If usedS Set pStatus="OK (SQL)"
If ('usedS)&(usedG) Set pStatus="OK (GLOBAL)"
If ('usedS)&('usedG) Set pStatus="SQL FAILED; GLOBAL FAILED"
Quit total

Set count=0
Set ts=""

For  {
    Set ts=$Order(^Ens.MessageHeaderI("TimeCreated",ts))
    Quit:ts=""

    ; NOTE: entire boolean inside postconditional. No trailing tokens. [1](https://docs.intersystems.com/irislatest/csp/docbook/DocBook.UI.Page.cls?KEY=GCOS_booleans)[2](https://docs.intersystems.com/irislatest/csp/docbook/DocBook.UI.Page.cls?KEY=RCOS_SYMBOLS)
    If pStartIncl {
        Continue:(pStartTS ]] ts)
    } Else {
        Continue:((pStartTS ]] ts)||(ts=pStartTS))
    }

    If pEndIncl {
        Quit:(ts ]] pEndTS)
    } Else {
        Quit:((ts ]] pEndTS)||(ts=pEndTS))
    }

    Set id=""
    For  {
        Set id=$Order(^Ens.MessageHeaderI("TimeCreated",ts,id))
        Quit:id=""
        Set count=count+1
    }
}

Quit count

Set ok=0 Set count=0 Set op1=$Select(pStartIncl:">=",1:">") Set op2=$Select(pEndIncl:"<=",1:"<") Set q="SELECT COUNT(*) FROM Ens.MessageHeader WHERE TimeCreated "_op1_" ? AND TimeCreated "_op2_" ?"
Set stmt="", rset="", sc=0 Try { Set stmt=##class(%SQL.Statement).%New() Set sc=stmt.%Prepare(q) If sc'=1 { Set ok=0 Goto Done } Set rset=stmt.%Execute(pStartTS,pEndTS) If rset.%Next() Set count=+$Get(rset.%Get(1)) Set ok=1 } Catch ex { Set ok=0 Set count=0 }
Done Quit count

Set ok=0
Set count=0

Set id=""
Set prevTC=""
Set monotonic=1
Set seenAfterStart=0

For  {
    Set id=$Order(^Ens.MessageHeaderD(id))
    Quit:id=""

    Set row=$Get(^Ens.MessageHeaderD(id))
    Continue:row=""

    Set tc=$ListGet(row,15)
    Continue:tc=""

    Set ok=1

    If prevTC'="" {
        If (prevTC ]] tc) Set monotonic=0
    }
    Set prevTC=tc

    ; start filter
    If pStartIncl {
        If (pStartTS ]] tc) Continue
    } Else {
        If (pStartTS ]] tc)!(tc=pStartTS)  Continue
    }
    Set seenAfterStart=1

    ; end filter + early stop when monotonic
    If pEndIncl {
        If (tc ]] pEndTS) {
            If seenAfterStart,monotonic Quit
            Continue
        }
    } Else {
        If (tc ]] pEndTS)!(tc=pEndTS) {
            If seenAfterStart,monotonic Quit
            Continue
        }
    }

    Set count=count+1
}

Quit count

Set ts=""
For  {
    Set ts=$Order(^Ens.MessageHeaderI("TimeCreated",ts))
    Quit:ts=""

    If pStartIncl {
        Continue:(pStartTS ]] ts)
    } Else {
        Continue:((pStartTS ]] ts)||(ts=pStartTS))
    }

    If pEndIncl {
        Quit:(ts ]] pEndTS)
    } Else {
        Quit:((ts ]] pEndTS)||(ts=pEndTS))
    }

    Set cntAtTs=0
    Set id=""
    For  {
        Set id=$Order(^Ens.MessageHeaderI("TimeCreated",ts,id))
        Quit:id=""
        Set cntAtTs=cntAtTs+1
    }
    Continue:cntAtTs=0

    Set monKey=$Extract(ts,1,7)
    Set monthCounts(monKey)=$Get(monthCounts(monKey))+cntAtTs

    Set h=$ZDATETIMEH(ts,3)
    Set day=$Piece(h,",",1)
    Set dow=$SYSTEM.SQL.DAYOFWEEK(h)
    Set offset=(dow+5)#7
    Set wkStartDay=day-offset
    Set wkKey=$ZDATE(wkStartDay,3)

    Set weekCounts(wkKey)=$Get(weekCounts(wkKey))+cntAtTs
    Set grandTotal=grandTotal+cntAtTs
}
Quit

    Set ok=0
    Set op1=$Select(pStartIncl:">=",1:">")
    Set op2=$Select(pEndIncl:"<=",1:"<")

    Set stmt="",stmt2="",sc=0,sc2=0

    Try {
        Set stmt=##class(%SQL.Statement).%New()
        Set q1="SELECT {fn SUBSTRING(TimeCreated,1,7)} AS mon, COUNT(*) AS cnt FROM Ens.MessageHeader WHERE TimeCreated "_op1_" ? AND TimeCreated "_op2_" ? GROUP BY {fn SUBSTRING(TimeCreated,1,7)} ORDER BY mon"
        Set sc=stmt.%Prepare(q1)
        If sc'=1 { Set ok=0  Goto Done }

        Set rset=stmt.%Execute(pStartTS,pEndTS)
        While rset.%Next() {
            Set mon=$Get(rset.%Get(1))
            Set cnt=+$Get(rset.%Get(2))
            If mon'="" {
                Set monthCounts(mon)=$Get(monthCounts(mon))+cnt
                Set grandTotal=grandTotal+cnt
            }
        }

        Set stmt2=##class(%SQL.Statement).%New()
        Set q2="SELECT DATEADD('day', -MOD(DAYOFWEEK(TimeCreated)+5,7), CAST(TimeCreated AS DATE)) AS wkStart, COUNT(*) AS cnt FROM Ens.MessageHeader WHERE TimeCreated "_op1_" ? AND TimeCreated "_op2_" ? GROUP BY wkStart ORDER BY wkStart"
        Set sc2=stmt2.%Prepare(q2)
        If sc2'=1 { Set ok=0  Goto Done }

        Set rset2=stmt2.%Execute(pStartTS,pEndTS)
        While rset2.%Next() {
            Set wkStart=$Get(rset2.%Get(1))
            Set cnt=+$Get(rset2.%Get(2))
            If wkStart'="" Set weekCounts(wkStart)=$Get(weekCounts(wkStart))+cnt
        }

        Set ok=1
    } Catch ex {
        Set ok=0
    }

Done
    Quit

Set ok=0
Set id=""
Set prevTC=""
Set monotonic=1
Set seenAfterStart=0

For  {
    Set id=$Order(^Ens.MessageHeaderD(id))
    Quit:id=""

    Set row=$Get(^Ens.MessageHeaderD(id))
    Continue:row=""

    Set tc=$ListGet(row,15)
    Continue:tc=""

    Set ok=1

    If prevTC'="" {
        If (prevTC ]] tc) Set monotonic=0
    }
    Set prevTC=tc

    ; start filter
    If pStartIncl {
        If (pStartTS ]] tc) Continue
    } Else {
        If (pStartTS ]] tc)!(tc=pStartTS) Continue
    }
    Set seenAfterStart=1

    ; end filter + early stop
    If pEndIncl {
        If (tc ]] pEndTS) {
            If seenAfterStart,monotonic Quit
            Continue
        }
    } Else {
        If (tc ]] pEndTS)!(tc=pEndTS) {
            If seenAfterStart,monotonic Quit
            Continue
        }
    }

    Set monKey=$Extract(tc,1,7)
    Set monthCounts(monKey)=$Get(monthCounts(monKey))+1

    Set h=$ZDATETIMEH(tc,3)
    Set day=$Piece(h,",",1)
    Set dow=$SYSTEM.SQL.DAYOFWEEK(h)
    Set offset=(dow+5)#7
    Set wkStartDay=day-offset
    Set wkKey=$ZDATE(wkStartDay,3)
    Set weekCounts(wkKey)=$Get(weekCounts(wkKey))+1

    Set grandTotal=grandTotal+1
}

Quit
